insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('bef8dea4-0965-4632-bc98-b50d16fe4581', 'استاد مازیار فلاحی', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=300&auto=format&fit=crop&q=80', 'سرمربی بین‌المللی و مدرس رسمی FIP', 'مدرک بین‌المللی FIP Level 2 اسلواکی و اسپانیا', 9, 4.96, 84, 'تهران', ARRAY['باشگاه پدل انقلاب تهران','باشگاه پدل شاهین پاسداران'], 950000, 'تمرکز بر اصول حرفه‌ای بازی شیشه، ضربات Bandeja و Vibora، تصحیح زاویه ایستادن و ساخت تاکتیک تیمی زوج‌های پدل. سابقه هدایت قهرمانان کشوری.', ARRAY['اصلاح تکنیک پایه','استراتژی و حرکت با شیشه','اسمش و والی سرعتی','آماده‌سازی مسابقات'], ARRAY['شنبه','دوشنبه','چهارشنبه','جمعه'], ARRAY['۰۸:۰۰','۰۹:۳۰','۱۶:۰۰','۱۷:۳۰','۱۹:۰۰']);
insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('fa6a99ab-6e5c-476f-9ab6-56a058689200', 'کاپیتان پریسا شریفی', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=300&auto=format&fit=crop&q=80', 'مربی اسبق تیم ملی پدل و قهرمان لیگ برتر', 'مدرک مربیگری درجه ۱ فدراسیون و آکادمی مادرید', 7, 4.92, 65, 'تهران', ARRAY['باشگاه پدل شاهین پاسداران','مجموعه پدل درکه'], 850000, 'متخصص در افزایش اعتماد به نفس در دفاع، بازی خوانی و ریتم ضربات. برگزاری کلینیک‌های ویژه بانوان و دونفره‌های هماهنگ.', ARRAY['دفاع و دیوار شیشه‌ای','کلینیک دونفره هماهنگ','آمادگی جسمانی اختصاصی پدل','تاکتیک ضد حمله'], ARRAY['یک‌شنبه','سه‌شنبه','پنج‌شنبه'], ARRAY['۰۹:۰۰','۱۰:۳۰','۱۵:۰۰','۱۶:۳۰','۱۸:۰۰']);
insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('8baed9a6-4be9-4c0e-b0bb-1433f0710a71', 'سامان یزدانی', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=300&auto=format&fit=crop&q=80', 'مربی رسمی و سرپرست آکادمی اسپادانا', 'مدرک مربیگری پدل فدراسیون بین‌المللی FIP', 5, 4.88, 47, 'اصفهان', ARRAY['آکادمی پدل اسپادانا اصفهان','مجموعه پرواز'], 750000, 'رویکرد تحلیلی به پدل مدرن، آنالیز ویدیویی ضربات شاگردان، برنامه‌ریزی تمرینات پرتاب توپ و موقعیت‌سنجی هوشمندانه در زمین.', ARRAY['آنالیز تصویری بازی','شات‌سلکشن (Shot Selection)','سرویس و ریترن تهاجمی'], ARRAY['شنبه','سه‌شنبه','چهارشنبه','جمعه'], ARRAY['۰۸:۳۰','۱۰:۰۰','۱۷:۰۰','۱۸:۳۰','۲۰:۰۰']);
insert into coaches (id, name, avatar_url, title, fip_certification, experience_years, rating, reviews_count, province, club_names, hourly_rate, bio, specialties, available_days, available_hours) values ('c0ee811f-a689-49cf-8b07-f3866e4cc1db', 'مهرشاد کیان‌پور', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=300&auto=format&fit=crop&q=80', 'مربی آکادمی مارینا کیش و متخصص استعدادیابی', 'مدرک مربیگری پیشرفته FIP Level 1', 6, 4.9, 52, 'هرمزگان', ARRAY['مجموعه بین‌المللی پدل مارینا کیش'], 850000, 'تجربه سال‌ها تمرین در آب‌وهوای ساحلی، بهینه‌سازی تنفس، بازی سرعتی نزدیک تور و آموزش تکنیک‌های پرطرفدار Bajada و Rulo.', ARRAY['ضربات نمایشی و کاربردی','کلینیک فشرده مسافرین کیش','قدرت و سرعت عکس‌العمل'], ARRAY['همه‌روزه'], ARRAY['۰۸:۰۰','۰۹:۳۰','۱۸:۰۰','۱۹:۳۰','۲۱:۰۰']);
